// scripts/build-playground-bundle.js
// Bundles @glyph/core into a single ESM file the playground can `import`.
// Browser target, no Node built-ins.

import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

await build({
  entryPoints: [resolve(root, "packages/core/dist/index.js")],
  bundle: true,
  format: "esm",
  target: "es2022",
  platform: "browser",
  outfile: resolve(root, "site/play/glyph-bundle.js"),
  minify: false, // readable — engineers should be able to view-source
  sourcemap: "linked",
  legalComments: "inline",
  banner: {
    js: "// glyph-bundle.js — generated by scripts/build-playground-bundle.js — do not edit",
  },
});

console.log("Wrote site/play/glyph-bundle.js");
